// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title TokenVault
 * @notice A secure vault for depositing and withdrawing ETH
 * @dev Demonstrates production-quality patterns for Web3 dApp integration
 */
contract TokenVault {
    // State variables
    mapping(address => uint256) public balances;
    uint256 public totalDeposits;
    address public owner;
    bool public paused;

    // Constants
    uint256 public constant MIN_DEPOSIT = 0.001 ether;
    uint256 public constant MAX_DEPOSIT = 10 ether;

    // Events - Critical for frontend synchronization
    event Deposited(address indexed user, uint256 amount, uint256 timestamp);
    event Withdrawn(address indexed user, uint256 amount, uint256 timestamp);
    event EmergencyWithdrawal(address indexed user, uint256 amount);
    event PausedStateChanged(bool isPaused);

    // Custom errors - More gas efficient than require strings
    error InsufficientDeposit();
    error ExcessiveDeposit();
    error InsufficientBalance();
    error ContractPaused();
    error OnlyOwner();
    error TransferFailed();
    error ZeroAmount();

    // Modifiers
    modifier onlyOwner() {
        if (msg.sender != owner) revert OnlyOwner();
        _;
    }

    modifier whenNotPaused() {
        if (paused) revert ContractPaused();
        _;
    }

    constructor() {
        owner = msg.sender;
        paused = false;
    }

    /**
     * @notice Deposit ETH into the vault
     * @dev Validates amount and updates state before external call
     */
    function deposit() external payable whenNotPaused {
        if (msg.value == 0) revert ZeroAmount();
        if (msg.value < MIN_DEPOSIT) revert InsufficientDeposit();
        if (msg.value > MAX_DEPOSIT) revert ExcessiveDeposit();

        balances[msg.sender] += msg.value;
        totalDeposits += msg.value;

        emit Deposited(msg.sender, msg.value, block.timestamp);
    }

    /**
     * @notice Withdraw ETH from the vault
     * @param amount Amount to withdraw in wei
     * @dev Follows checks-effects-interactions pattern
     */
    function withdraw(uint256 amount) external whenNotPaused {
        if (amount == 0) revert ZeroAmount();
        if (balances[msg.sender] < amount) revert InsufficientBalance();

        // Effects - Update state before external call
        balances[msg.sender] -= amount;
        totalDeposits -= amount;

        // Interactions - External call last
        (bool success, ) = msg.sender.call{value: amount}("");
        if (!success) revert TransferFailed();

        emit Withdrawn(msg.sender, amount, block.timestamp);
    }

    /**
     * @notice Emergency withdrawal of all funds
     * @dev Available even when paused
     */
    function emergencyWithdraw() external {
        uint256 amount = balances[msg.sender];
        if (amount == 0) revert InsufficientBalance();

        balances[msg.sender] = 0;
        totalDeposits -= amount;

        (bool success, ) = msg.sender.call{value: amount}("");
        if (!success) revert TransferFailed();

        emit EmergencyWithdrawal(msg.sender, amount);
    }

    /**
     * @notice Get user's current balance
     * @param user Address to check
     * @return Current balance in wei
     */
    function getBalance(address user) external view returns (uint256) {
        return balances[user];
    }

    /**
     * @notice Get contract's total ETH balance
     * @return Total ETH held in contract
     */
    function getContractBalance() external view returns (uint256) {
        return address(this).balance;
    }

    /**
     * @notice Toggle pause state (owner only)
     * @dev Used for emergency stops
     */
    function togglePause() external onlyOwner {
        paused = !paused;
        emit PausedStateChanged(paused);
    }

    /**
     * @notice Check if contract is paused
     * @return Current pause state
     */
    function isPaused() external view returns (bool) {
        return paused;
    }
}

